return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'am_ET','project-id-version'=>'Events Manager','pot-creation-date'=>'2026-11-16T04:45:03+00:00','po-revision-date'=>'2026-11-15 11:46:08+0000','x-generator'=>'Pixelite GlotPress Sync','messages'=>[' Maximum size permitted by WordPress is %s.'=>' በ WordPress የሚፈቀደው ከፍተኛ መጠን %s ነው።',' is required.'=>' ያስፈልጋል።','"%1$s" could not be created: %2$s'=>'"%1$s" መፍጠር አልተቻለም፦ %2$s','"%1$s" is not a field. Fields: %2$s.'=>'"%1$s" መስክ አይደለም። መስኮች፦ %2$s።','"%s" is neither a media ID nor a web address that can be reached.'=>'"%s" የሚዲያ መታወቂያም ሆነ ሊደረስበት የሚችል የድር አድራሻ አይደለም።','"All events" link text'=>'የ«ሁሉም ዝግጅቶች» ሊንክ ጽሑፍ','#s will be replaced by the date format below'=>'#s በታች ባለው የቀን ቅርጸት ይተካል','%1$s could not be updated yet, and Events Manager will keep retrying in the background: %2$s'=>'%1$s ገና ማዘመን አልተቻለም፣ እና Events Manager በጀርባ እንደገና መሞከሩን ይቀጥላል፦ %2$s','%1$s of %2$s'=>'%1$s ከ%2$s','%1$s recommends %2$s version %3$s or greater installed. Earlier versions may cause unexpected issues.'=>'%1$s የ%2$s ሥሪት %3$s ወይም ከዚያ በላይ እንዲጫን ይመክራል። ቀደምት ሥሪቶች ያልተጠበቁ ችግሮችን ሊያስከትሉ ይችላሉ።','%1$s requires %2$s version %3$s or greater installed.'=>'%1$s የ%2$s ሥሪት %3$s ወይም ከዚያ በላይ መጫን ያስፈልገዋል።','%1$s was updated, but the result could not be stored: %2$s'=>'%1$s ተዘምኗል፣ ነገር ግን ውጤቱን ማስቀመጥ አልተቻለም፦ %2$s','%1$s will be set up automatically on %2$s.'=>'%1$s በ%2$s በራስ-ሰር ይዘጋጃል።','%1$s: %2$d rows imported, %3$d skipped.'=>'%1$s፦ %2$d ረድፎች ገብተዋል፣ %3$d ተዘልለዋል።','%d Attendees'=>'%d ተሳታፊዎች','%d Pattern'=>'%d ንድፍ' . "\0" . '%d ንድፎች','%d Spaces'=>'%d ቦታዎች','%d Tickets'=>'%d ትኬቶች','%d date'=>'%d ቀን' . "\0" . '%d ቀኖች','%d events have been %s as they no longer match the recurrence pattern.'=>'ከድግግሞሽ ንድፍ ጋር ስለማይዛመዱ %d ዝግጅቶች %s ተደርገዋል።','%d more rows are not listed.'=>'ሌሎች %d ረድፎች አልተዘረዘሩም።','%d potentially orphaned events have been found.'=>'%d ወላጅ አልባ ሊሆኑ የሚችሉ ዝግጅቶች ተገኝተዋል።','%d space'=>'%d ቦታ' . "\0" . '%d ቦታዎች','%d ticket belongs to a recurring event or series pass; each date of the migrated recurring event gets its own copy of the ticket, and each series pass order becomes one booking per date.'=>'%d ትኬት የአንድ ተደጋጋሚ ዝግጅት ወይም የተከታታይ ማለፊያ ነው፤ የተሸጋገረው ተደጋጋሚ ዝግጅት እያንዳንዱ ቀን የራሱ የትኬት ቅጂ ያገኛል፣ እና እያንዳንዱ የተከታታይ ማለፊያ ትዕዛዝ በቀን አንድ ቦታ ማስያዝ ይሆናል።' . "\0" . '%d ትኬቶች የተደጋጋሚ ዝግጅቶች ወይም የተከታታይ ማለፊያዎች ናቸው፤ የተሸጋገረው ተደጋጋሚ ዝግጅት እያንዳንዱ ቀን የራሱ የትኬት ቅጂ ያገኛል፣ እና እያንዳንዱ የተከታታይ ማለፊያ ትዕዛዝ በቀን አንድ ቦታ ማስያዝ ይሆናል።','%d will be replaced by a number.'=>'%d በቁጥር ይተካል።','%s'=>'%s','%s (the link is provided after booking)'=>'%s (አገናኙ ከቦታ ማስያዝ በኋላ ይሰጣል)','%s (the link is provided once your booking is confirmed)'=>'%s (አገናኙ ቦታ ማስያዝዎ ከተረጋገጠ በኋላ ይሰጣል)','%s (your booking does not include virtual access)'=>'%s (ቦታ ማስያዝዎ ምናባዊ መዳረሻን አያካትትም)','%s Advanced Options'=>'%s የላቁ አማራጮች','%s App ID'=>'የ%s መተግበሪያ መታወቂያ','%s App Secret'=>'የ%s መተግበሪያ ሚስጥር','%s Attributes'=>'%s ባህሪዎች','%s Between'=>'%s መካከል','%s Capabilities'=>'የ%s ችሎታዎች','%s Error. Try again?'=>'%s ስህተት። እንደገና ይሞክሩ?','%s Excerpts'=>'%s ቅንጭቦች','%s ID'=>'%s መታወቂያ','%s List Formats'=>'የ%s ዝርዝር ቅርጸቶች','%s List/Archives'=>'%s ዝርዝር/መዝገቦች','%s Options'=>'%s አማራጮች','%s Page'=>'%s ገጽ','%s Pages'=>'%s ገጾች','%s Preview Mode'=>'%s የቅድሚያ እይታ ሁነታ','%s Recurrences'=>'%s ድግግሞሾች','%s Rows'=>'%s ረድፎች','%s Settings'=>'%s ቅንብሮች','%s Span Between'=>'የ%s ልዩነት መካከል','%s Status'=>'የ%s ሁኔታ','%s Submitted'=>'%s ገብቷል','%s URL'=>'የ%s ዩአርኤል','%s added the event %s'=>'%s ዝግጅቱን %s ጨምሯል','%s added the event %s to %s.'=>'%s ዝግጅቱን %s ወደ %s ጨምሯል።','%s allows you to modify some or all of the formats used by Events Manager to generate your content. You can choose to override default formats and customize them to your needs. You do not lose your previously defined custom formats should you enable/disable %s or choose to not override a certain set of formats, they\'ll appear again once you enable %s again for that content.'=>'%s Events Manager ይዘትዎን ለማመንጨት የሚጠቀምባቸውን ቅርጸቶች በከፊል ወይም በሙሉ እንዲቀይሩ ያስችልዎታል። ነባሪ ቅርጸቶችን መሻር እና እንደ ፍላጎትዎ ማበጀት ይችላሉ። %s ቢያነቁ/ቢያሰናክሉ ወይም የተወሰኑ ቅርጸቶችን ላለመሻር ቢመርጡ ቀደም ብለው ያበጇቸው ቅርጸቶች አይጠፉም፣ ለዚያ ይዘት %s እንደገና ሲያነቁ እንደገና ይታያሉ።','%s are a <a href="%s" target="_blank">WordPress custom taxonomy</a>.'=>'%s <a href="%s" target="_blank">የWordPress ብጁ ታክሶኖሚ</a> ናቸው።','%s are also accepted, for example %s equals 1 month and 12 hours before the event starts.'=>'%s እንዲሁ ተቀባይነት አላቸው፣ ለምሳሌ %s ማለት ዝግጅቱ ከመጀመሩ 1 ወር እና 12 ሰዓት በፊት ማለት ነው።','%s belonging to other sub-sites will have an extra slug prepended to it so that your main site can differentiate between its own %s and those belonging to other sites in your network.'=>'የሌሎች ንዑስ ጣቢያዎች %s ዋናው ጣቢያዎ የራሱን %s ከሌሎች የአውታረ መረብዎ ጣቢያዎች ከሆኑት እንዲለይ ተጨማሪ ስሉግ ይቀደምላቸዋል።','%s can be displayed just like normal WordPress custom taxonomies in an archive-style format, however Events Manager by default allows you to completely change the standard look of these archives and use our own <a href="%s">custom formatting</a> methods.'=>'%s እንደ መደበኛ የWordPress ብጁ ታክሶኖሚዎች በመዝገብ ቅርጸት ሊታዩ ይችላሉ፣ ሆኖም Events Manager በመደበኛነት የእነዚህን መዝገቦች መደበኛ መልክ ሙሉ በሙሉ እንዲቀይሩ እና የራሳችንን <a href="%s">ብጁ ቅርጸት</a> ዘዴዎች እንዲጠቀሙ ያስችልዎታል።','%s cannot be used for a hybrid event, because it gives every booking virtual access.'=>'%s ለድቅል ዝግጅት መጠቀም አይቻልም፣ ምክንያቱም ለእያንዳንዱ ቦታ ማስያዝ ምናባዊ መዳረሻ ይሰጣል።','%s could not be deleted'=>'%s መሰረዝ አልተቻለም','%s could not be deleted.'=>'%s ሊሰረዝ አልቻለም።','%s created.'=>'%s ተፈጥሯል።','%s custom post types can have archives, just like normal WordPress posts. If enabled, should you visit your base slug url %s and you will see an post-formatted archive of previous %s'=>'%s ብጁ የፖስት ዓይነቶች እንደ መደበኛ የWordPress ፖስቶች መዝገቦች ሊኖራቸው ይችላል። ከነቃ፣ የመሠረት ቁራጭ ዩአርኤልዎን %s ከጎበኙ የቀደሙ %s በፖስት ቅርጸት የተዘጋጀ መዝገብ ያያሉ','%s deleted'=>'%s ተሰርዟል','%s excerpt'=>'%s ቅንጭብ','%s excerpt fallback'=>'%s ቅንጭብ መመለሻ','%s includes every add-on sold here.'=>'%s እዚህ የሚሸጡትን ሁሉንም ተጨማሪዎች ያካትታል።','%s is attending %s of the group %s.'=>'%s የቡድን %s ዝግጅት %s ላይ ይሳተፋል።','%s is attending %s.'=>'%s በ%s ላይ ይሳተፋል።','%s is replaced by username, %s is replaced by the user password and %s is replaced by a link to create a password.'=>'%s በተጠቃሚ ስም፣ %s በተጠቃሚው የይለፍ ቃል፣ %s ደግሞ የይለፍ ቃል ለመፍጠር በሚያስችል ሊንክ ይተካል።','%s is required.'=>'%s ያስፈልጋል።','%s item'=>'%s ንጥል' . "\0" . '%s ንጥሎች','%s list footer format'=>'የ%s ዝርዝር ግርጌ ቅርጸት','%s list header format'=>'የ%s ዝርዝር ራስጌ ቅርጸት','%s list item format'=>'የ%s ዝርዝር ንጥል ቅርጸት','%s must be set to yes for this to work.'=>'ይህ እንዲሠራ %s አዎ መሆን አለበት።','%s overrides all formatting choices, which will be be taken from the settings defined on this page. If you want to override only certain formatting, choose the %s instead.'=>'%s ሁሉንም የቅርጸት ምርጫዎች ይሽራል፣ ቅርጸቶቹም በዚህ ገጽ ላይ ከተገለጹት ቅንብሮች ይወሰዳሉ። የተወሰኑ ቅርጸቶችን ብቻ መሻር ከፈለጉ በምትኩ %s ይምረጡ።','%s page'=>'%s ገጽ','%s parameters will be permitted in shortcode.'=>'%s ግቤቶች በሾርትኮዱ ውስጥ ይፈቀዳሉ።','%s row'=>'%s ረድፍ' . "\0" . '%s ረድፎች','%s successfully deleted'=>'%s በተሳካ ሁኔታ ተሰርዟል','%s successfully deleted.'=>'%s በተሳካ ሁኔታ ተሰርዟል።','%s successfully duplicated.'=>'%s በተሳካ ሁኔታ ተባዝቷል።','%s users cancelled bookings.'=>'%s ተጠቃሚዎች ቦታ ማስያዣዎችን ሰርዘዋል።','%s will be replaced by a link to your site privacy policy page.'=>'%s በጣቢያዎ የግላዊነት ፖሊሲ ገጽ ሊንክ ይተካል።','%s will not be attending %s anymore.'=>'%s ከአሁን በኋላ በ%s ላይ አይሳተፍም።','%s will not be attending %s of group %s anymore.'=>'%s ከአሁን በኋላ የቡድን %s ዝግጅት %s ላይ አይሳተፍም።','(New)'=>'(አዲስ)','(always available)'=>'(ሁልጊዜ ይገኛል)','(not applicable with event ownership on presently, coming soon!)'=>'(የዝግጅት ባለቤትነት በአሁኑ ጊዜ ሲበራ አይሠራም፣ በቅርቡ ይመጣል!)','1,2,3 or 2 (0 = all)'=>'1,2,3 ወይም 2 (0 = ሁሉም)','1. Match columns'=>'1. ዓምዶችን አዛምድ','2 for every second day, week, month or year. Leave empty for every one.'=>'2 ለእያንዳንዱ ሁለተኛ ቀን፣ ሳምንት፣ ወር ወይም ዓመት። ለሁሉም ባዶ ይተዉት።','2. Options'=>'2. አማራጮች','3. Preview'=>'3. ቅድመ እይታ','<a href="%s">See some more information</a> on how %s work when overriding with formats.'=>'በቅርጸቶች ሲተኩ %s እንዴት እንደሚሠሩ <a href="%s">ተጨማሪ መረጃ ይመልከቱ</a>።','<a href="%s">Visit our blog</a> for the latest news about recent updates.'=>'ስለ የቅርብ ጊዜ ዝመናዎች የቅርብ ጊዜ ዜናዎችን ለማግኘት <a href="%s">ብሎጋችንን ይጎብኙ</a>።','<li>No events in this location</li>'=>'<li>በዚህ አካባቢ ምንም ዝግጅቶች የሉም</li>','<p>Events Manager is ready to go! It is highly recommended you read the <a href=\'%s\'>Getting Started</a> guide on our site, as well as checking out the <a href=\'%s\'>Settings Page</a></p>'=>'<p>Events Manager ለመጠቀም ዝግጁ ነው! በጣቢያችን ላይ ያለውን <a href=\'%s\'>መጀመሪያ ጀምር</a> መመሪያ እንዲያነቡ እንዲሁም <a href=\'%s\'>የቅንብሮች ገጹን</a> እንዲመለከቱ በጣም ይመከራል</p>','<strong>ERROR</strong>: Couldn&#8217;t register you... please contact the <a href="mailto:%s">webmaster</a> !'=>'<strong>ስህተት</strong>፦ ሊመዘግቡዎት አልቻሉም... እባክዎ <a href="mailto:%s">ድር አስተዳዳሪውን</a> ያግኙ!','<strong>ERROR</strong>: Please enter a username.'=>'<strong>ስህተት</strong>: የመጠቀሚያ ስመዎን ያስገቡ።','<strong>ERROR</strong>: Please type your e-mail address.'=>'<strong>ስህተት</strong>: የ ኤ-ደብዳቤ አድራሻዎን ይጻፉ።','<strong>ERROR</strong>: The email address isn&#8217;t correct.'=>'<strong>ስህተት</strong>: ኤ-ደብዳቤ አድራሻው ትክክል አይደለም።','<strong>ERROR</strong>: This email is already registered, please choose another one.'=>'<strong>ስህተት</strong>፤ ይህ ኤ-ደብዳቤ ከዚህ በፊት የተመዘገበ ስለሆነ ሌላ ይምረጡ።','<strong>ERROR</strong>: This username is already registered, please choose another one.'=>'<strong>ስህተት</strong>፦ ይህ የተጠቃሚ ስም አስቀድሞ ተመዝግቧል፣ እባክዎ ሌላ ይምረጡ።','<strong>ERROR</strong>: This username is invalid because it uses illegal characters. Please enter a valid username.'=>'<strong>ስህተት</strong>: ይህ የተጠቃሚ ስም አይሰራም። ምክንያቱም የማይታወቁ ቁምፊወች ጨምሯል። የሚሰራ የተጠቃሚ ስም ያስገቡ።','<strong>Notes:</strong> Ticket availability not taken into account (i.e. you can overbook). Emails are not resent automatically.'=>'<strong>ማስታወሻ፦</strong> የትኬት ተገኝነት ከግምት ውስጥ አይገባም (ማለትም ከአቅም በላይ ማስያዝ ይችላሉ)። ኢሜይሎች በራስ-ሰር እንደገና አይላኩም።','<strong>Notes:</strong> Ticket availability not taken into account when approving new bookings (i.e. you can overbook).'=>'<strong>ማስታወሻ፦</strong> አዲስ ቦታ ማስያዣዎችን ሲያጸድቁ የትኬት ተገኝነት ከግምት ውስጥ አይገባም (ማለትም ከአቅም በላይ ማስያዝ ይችላሉ)።','<strong>Warning : </strong> By enabling this, registered users will not be able to see bookings they make as guests in their "My Bookings" page.'=>'<strong>ማስጠንቀቂያ፥ </strong> ይህን በማንቃት፣ የተመዘገቡ ተጠቃሚዎች እንደ እንግዳ ያደረጓቸውን ቦታ ማስያዣዎች በ"ቦታ ማስያዣዎቼ" ገጻቸው ላይ ማየት አይችሉም።','<strong>Warning : </strong> Various features afforded to users with an account will not be available, e.g. viewing bookings. Once you enable this and select a user, modifying these values will prevent older non-user bookings from displaying the correct information.'=>'<strong>ማስጠንቀቂያ፥ </strong> መለያ ላላቸው ተጠቃሚዎች የሚሰጡ የተለያዩ ባህሪያት አይገኙም፣ ለምሳሌ ቦታ ማስያዣዎችን ማየት። ይህን አንዴ ካነቁና ተጠቃሚ ከመረጡ በኋላ እነዚህን ዋጋዎች መቀየር የቆዩ ተጠቃሚ-አልባ ቦታ ማስያዣዎች ትክክለኛውን መረጃ እንዳያሳዩ ያደርጋል።','A booking intent cannot have its status changed.'=>'የቦታ ማስያዝ ፍላጎት ሁኔታ ሊቀየር አይችልም።','A booking was cancelled'=>'አንድ ቦታ ማስያዝ ተሰርዟል','A booking\'s payment gateway is set when the booking is made and cannot be changed.'=>'የቦታ ማስያዣ የክፍያ መተላለፊያ ቦታ ማስያዣው ሲደረግ ይወሰናል፣ ሊቀየርም አይችልም።','A guest-accessible cancellation flow for the EU statutory <strong>right of withdrawal</strong>. Enable this only if you sell to consumers who have a right of withdrawal — <strong>fixed-date events are generally exempt</strong>. Events Manager provides the mechanism; you supply your own legal withdrawal policy text below.'=>'ለአውሮፓ ህብረት ህጋዊ <strong>የመውጣት መብት</strong> እንግዳ የሚደርስበት የመሰረዝ ሂደት። ይህንን የሚያነቁት የመውጣት መብት ላላቸው ሸማቾች ከሸጡ ብቻ ነው፣ <strong>የተወሰነ ቀን ያላቸው ዝግጅቶች በአጠቃላይ ነጻ ናቸው</strong>። Events Manager ዘዴውን ያቀርባል፤ የራስዎን ህጋዊ የመውጣት ፖሊሲ ጽሑፍ ከታች ያቅርቡ።','A hybrid event needs a physical venue.'=>'ድቅል ዝግጅት አካላዊ ስፍራ ያስፈልገዋል።','A list of further dates, such as 2027-03-11|2027-03-18, used alone or with a rule.'=>'ተጨማሪ ቀኖች ዝርዝር፣ ለምሳሌ 2027-03-11|2027-03-18፣ ብቻውን ወይም ከደንብ ጋር ጥቅም ላይ የሚውል።','A location with this name is already on this site (location %d).'=>'በዚህ ስም ያለ አካባቢ በዚህ ጣቢያ ላይ አለ (አካባቢ %d)።','A location with this name is already on this site.'=>'በዚህ ስም ያለ አካባቢ በዚህ ጣቢያ ላይ አለ።','A new event has been published by #_CONTACTNAME.<br/>Name : #_EVENTNAME <br/>Date : #_EVENTDATES <br/>Time : #_EVENTTIMES <br/>Edit this event - #_EDITEVENTURL <br/> View this event - #_EVENTURL'=>'አዲስ ዝግጅት በ#_CONTACTNAME ታትሟል።<br/>ስም : #_EVENTNAME <br/>ቀን : #_EVENTDATES <br/>ሰዓት : #_EVENTTIMES <br/>ይህን ዝግጅት አርም - #_EDITEVENTURL <br/> ይህን ዝግጅት ይመልከቱ - #_EVENTURL','A new event has been submitted by #_CONTACTNAME.<br/>Name : #_EVENTNAME <br/>Date : #_EVENTDATES <br/>Time : #_EVENTTIMES <br/>Please visit #_EDITEVENTURL to review this event for approval.'=>'አዲስ ዝግጅት በ#_CONTACTNAME ገብቷል።<br/>ስም : #_EVENTNAME <br/>ቀን : #_EVENTDATES <br/>ሰዓት : #_EVENTTIMES <br/>ይህን ዝግጅት ለማጽደቅ ለመገምገም እባክዎ #_EDITEVENTURL ን ይጎብኙ።','A new event was created'=>'አዲስ ዝግጅት ተፈጥሯል','A new user account has been created for you. Please check your email for access details.'=>'አዲስ የተጠቃሚ መለያ ተፈጥሮልዎታል። የመግቢያ መረጃውን ለማግኘት እባክዎ ኢሜይልዎን ይመልከቱ።','A previously published event has been modified by #_CONTACTNAME, and this event is now unpublished and pending your approval.<br/>Name : #_EVENTNAME <br/>Date : #_EVENTDATES <br/>Time : #_EVENTTIMES <br/>Please visit #_EDITEVENTURL to review this event for approval.'=>'ቀደም ሲል የታተመ ዝግጅት በ#_CONTACTNAME ተሻሽሏል፣ ስለዚህ ይህ ዝግጅት አሁን ያልታተመ ሲሆን የእርስዎን ማረጋገጫ በመጠበቅ ላይ ነው።<br/>ስም : #_EVENTNAME <br/>ቀን : #_EVENTDATES <br/>ሰዓት : #_EVENTTIMES <br/>ይህን ዝግጅት ለማጽደቅ ለመገምገም እባክዎ #_EDITEVENTURL ን ይጎብኙ።','A repeating event needs a repeat-until date or a number of times.'=>'ተደጋጋሚ ዝግጅት እስከሚደጋገምበት ቀን ወይም የድግግሞሽ ብዛት ያስፈልገዋል።','A test email will be sent to your account email - %s'=>'የሙከራ ኢሜይል ወደ መለያዎ ኢሜይል ይላካል - %s','A token is required.'=>'ቶከን ያስፈልጋል።','A user cancelled a booking'=>'አንድ ተጠቃሚ ቦታ ማስያዣ ሰርዟል','A valid Expo push token is required.'=>'ልክ የሆነ የ Expo ፑሽ ቶከን ያስፈልጋል።','A valid blog ID must be provided, you can only reset one blog at a time.'=>'ትክክለኛ የጦማር መታወቂያ መቅረብ አለበት፣ በአንድ ጊዜ አንድ ጦማር ብቻ ዳግም ማቀናበር ይችላሉ።','A valid email'=>'ልክ የሆነ ኢሜይል','A virtual event can hold its link back until shortly before it starts. Until then, visitors and attendees see a short text in place of the link, and join links sent to attendees only start working at that time.'=>'ምናባዊ ዝግጅት አገናኙን ከመጀመሩ ጥቂት ቀደም ብሎ እስኪሆን ድረስ መያዝ ይችላል። እስከዚያ ድረስ ጎብኚዎችና ተሳታፊዎች በአገናኙ ቦታ አጭር ጽሑፍ ያያሉ፣ ለተሳታፊዎች የተላኩ የመቀላቀያ አገናኞችም መስራት የሚጀምሩት በዚያ ሰዓት ነው።','AFTER the withdrawal period — please review carefully'=>'ከመውጣት ጊዜ በኋላ ከሆነ። እባክዎ በጥንቃቄ ይገምግሙ','AI / MCP Setup'=>'የAI / MCP ማዋቀር','Abbreviated weekdays'=>'የተጠራዘዙ የሳምንት ቀናት','Abbreviated weekdays?'=>'የተጠራዘዙ የሳምንት ቀናት?','Abilities that create, update, delete, or otherwise modify Events Manager data.'=>'የEvents Manager ውሂብን የሚፈጥሩ፣ የሚያዘምኑ፣ የሚሰርዙ ወይም በሌላ መንገድ የሚቀይሩ ችሎታዎች።','Access'=>'መዳረሻ','Accordion'=>'አኮርዲዮን','Account Connection'=>'የመለያ ግንኙነት','Acknowledgment email'=>'የደረሰኝ እውቅና ኢሜይል','Acknowledgment email body'=>'የእውቅና ኢሜይል አካል','Acknowledgment email subject'=>'የእውቅና ኢሜይል ርዕሰ ጉዳይ','Actions'=>'እርምጃዎች','Activate license'=>'ፈቃድ አግብር','Activate plugin'=>'ተሰኪውን አግብር','Active'=>'ንቁ','Add %s'=>'%s ጨምር','Add Dates '=>'ቀኖችን ጨምር ','Add Event'=>'ዝግጅት ጨምር','Add Location'=>'አካባቢ ጨምር','Add New'=>'አዲስ አክል','Add New %s'=>'አዲስ %s አክል','Add New Archetype'=>'አዲስ አርኪታይፕ አክል','Add New Event'=>'አዲስ ዝግጅት አክል','Add New Event Category'=>'አዲስ የዝግጅት ምድብ አክል','Add New Event Tag'=>'አዲስ የዝግጅት መለያ አክል','Add New Location'=>'አዲስ አካባቢ አክል','Add New Repeating Event'=>'አዲስ ተደጋጋሚ ዝግጅት አክል','Add Note'=>'ማስታወሻ ጨምር','Add Repeating Event'=>'ተደጋጋሚ ዝግጅት አክል','Add Reply-To booker?'=>'ለቦታ አስያዡ መልስ-ወደ ይጨመር?','Add Reply-To event owner?'=>'ለዝግጅት ባለቤት መልስ-ወደ ይጨመር?','Add Time Slot'=>'የሰዓት ክፍተት ጨምር','Add To Calendar'=>'ወደ ቀን መቁጠሪያ ጨምር','Add a negative number or minus sign to the start of the date interval to allow cancellations after events have started.'=>'ዝግጅቶች ከተጀመሩ በኋላ ስረዛዎችን ለመፍቀድ ከቀን ክፍተቱ መጀመሪያ ላይ አሉታዊ ቁጥር ወይም የመቀነስ ምልክት ያክሉ።','Add a start or end date (or both) to impose time constraints on ticket availability. Leave either blank for no upper/lower limit.'=>'በትኬት መገኘት ላይ የጊዜ ገደብ ለመጣል መጀመሪያ ወይም መጨረሻ ቀን (ወይም ሁለቱንም) ያክሉ። ለላይኛ/ታችኛ ገደብ አለመኖር ሁለቱንም ባዶ ይተዉ።','Add a tax rate to your ticket prices (entering 10 will add 10% to the ticket price).'=>'ለትኬት ዋጋዎችዎ የግብር መጠን ያክሉ (10 ማስገባት በትኬቱ ዋጋ ላይ 10% ይጨምራል)።','Add any of these columns to an events file. A row with none of them filled in is a single event.'=>'ከእነዚህ ዓምዶች ማንኛውንም ወደ የዝግጅቶች ፋይል ያክሉ። ከእነዚህ አንዳቸውም ያልተሞላበት ረድፍ ነጠላ ዝግጅት ነው።','Add br tags to HTML emails?'=>'ወደ ኤችቲኤምኤል ኢሜይሎች br መለያዎችን ጨምር?','Add location'=>'አካባቢ ጨምር','Add new ticket'=>'አዲስ ትኬት ጨምር','Add or remove %s'=>'%s ጨምር ወይም አስወግድ','Add or remove events'=>'ዝግጅቶችን ጨምር ወይም አስወግድ','Add tax to ticket price?'=>'በትኬት ዋጋ ላይ ግብር ይጨመር?','Add to your table from the columns below.'=>'ከታች ካሉት አምዶች ወደ ሰንጠረዥዎ ይጨምሩ።','Add-ons'=>'ተጨማሪዎች','Add-ons and prices are up to date.'=>'ተጨማሪዎችና ዋጋዎች ወቅታዊ ናቸው።','Add-ons are separate plugins that work with the free Events Manager plugin, so you do not need Events Manager Pro to use them.'=>'ተጨማሪዎች ከነፃው Events Manager ተሰኪ ጋር የሚሰሩ የተለዩ ተሰኪዎች ናቸው፣ ስለዚህ እነሱን ለመጠቀም Events Manager Pro አያስፈልግዎትም።','Additional CSS'=>'ተጨማሪ CSS','Address'=>'አድራሻ','Address line 2'=>'የአድራሻ መስመር 2','Address only'=>'አድራሻ ብቻ','Address:'=>'አድራሻ፦','Adds a checkbox below the location options that limits results to events attendees can join virtually, including hybrid events.'=>'ከአካባቢ አማራጮች በታች ውጤቶችን ተሳታፊዎች በምናባዊ መንገድ ሊቀላቀሉባቸው ወደሚችሉ ዝግጅቶች፣ ድቅል ዝግጅቶችን ጨምሮ፣ የሚገድብ ምልክት ማድረጊያ ሳጥን ያክላል።','Adds a guest-accessible withdrawal flow and, optionally, a site-wide footer link.'=>'እንግዳ የሚደርስበት የመውጣት ሂደት እና እንደ አማራጭ በመላው ጣቢያ የግርጌ አገናኝ ይጨምራል።','Adds the time and the hidden text to the event editor, so each event can set its own. If not, every event uses the defaults below.'=>'ሰዓቱንና የተደበቀውን ጽሑፍ ወደ የዝግጅት አርታዒ ያክላል፣ ስለዚህ እያንዳንዱ ዝግጅት የራሱን ማዘጋጀት ይችላል። ካልሆነ እያንዳንዱ ዝግጅት ከታች ያሉትን መደበኛ ቅንብሮች ይጠቀማል።','Admin Icon'=>'የአስተዳዳሪ አዶ','Admin Tools'=>'የአስተዳዳሪ መሳሪያወች','Administrator Email'=>'የአስተዳዳሪ ኢሜይል','Advanced'=>'የላቀ','Advanced Mode'=>'የላቀ ሁነታ','Advanced Search Fields'=>'የላቁ የፍለጋ መስኮች','Advanced search mode'=>'የላቀ ፍለጋ ሁነታ','Advanced search style'=>'የላቀ ፍለጋ ቅጥ','Advanced settings'=>'የላቁ ቅንብሮች','After'=>'በኋላ','All'=>'ሁሉም','All %s'=>'ሁሉም %s','All Ascending'=>'ሁሉም ሽቅብ','All Blogs'=>'ሁሉም ጦማሮች','All Categories'=>'ሁሉም ምድቦች','All Cities/Towns'=>'ሁሉም ከተሞች/ትናንሽ ከተሞች','All Countries'=>'ሁሉም አገሮች','All Day'=>'ሙሉ ቀን','All Day Message'=>'የቀኑን ሙሉ መልእክት','All Descending'=>'ሁሉም ቁልቁል','All Event Categories'=>'ሁሉም የዝግጅት ምድቦች','All Event Tags'=>'ሁሉም የዝግጅት መለያዎች','All Event Types'=>'ሁሉም የዝግጅት ዓይነቶች','All Events'=>'ሁሉም ዝግጅቶች','All Regions'=>'ሁሉም ክልሎች','All States'=>'ሁሉም ግዛቶች','All Tags'=>'ሁሉም መለያዎች','All Time'=>'ሁሉም ጊዜ','All Timeslots'=>'ሁሉንም የጊዜ ክፍሎች','All confirmed and pending bookings will be emailed a general event cancellation notification.'=>'ሁሉም የተረጋገጡ እና ያልተቋጩ ቦታ ማስያዣዎች አጠቃላይ የዝግጅት መሰረዝ ማሳወቂያ በኢሜይል ይደርሳቸዋል።','All countries text'=>'የሁሉም ሀገሮች ጽሑፍ','All day'=>'ቀኑን ሙሉ','All day (yes or no)'=>'ቀኑን ሙሉ (yes ወይም no)','All events'=>'ሁሉም ዝግጅቶች','All events link text?'=>'የ«ሁሉም ዝግጅቶች» ሊንክ ጽሑፍ?','All events will be moved to trash.'=>'ሁሉም ዝግጅቶች ወደ መጣያ ይወሰዳሉ።','All options below relate to data that may have been submitted by or collected from the user requesting their personal data, which would also include events and locations where they are the author.'=>'ከታች ያሉት ሁሉም አማራጮች የግል ውሂባቸውን በሚጠይቀው ተጠቃሚ የገባ ወይም ከእሱ የተሰበሰበ ውሂብን ይመለከታሉ፣ ይህም እሱ ደራሲ የሆነባቸውን ዝግጅቶች እና አካባቢዎችንም ያካትታል።','All our sold add-ons'=>'የምንሸጣቸው ሁሉም ተጨማሪዎች','All regions text'=>'የሁሉም ክልሎች ጽሑፍ','All settings, events and bookings for every site on this network will be permanently deleted. This cannot be undone.'=>'በዚህ አውታረ መረብ ላይ ያሉ የሁሉም ጣቢያዎች ቅንብሮች፣ ዝግጅቶች እና ቦታ ማስያዣዎች እስከመጨረሻው ይሰረዛሉ። ይህ ወደ ኋላ ሊመለስ አይችልም።','All states text'=>'የሁሉም ግዛቶች ጽሑፍ','All towns/cities text'=>'የሁሉም ትናንሽ ከተሞች/ከተሞች ጽሑፍ','All translations of this event will be detached from the recurring event.'=>'የዚህ ዝግጅት ሁሉም ትርጉሞች ከተደጋጋሚው ዝግጅት ይለያያሉ።','All your settings and events will be permanently deleted. This cannot be undone.'=>'ሁሉም ቅንብሮችዎ እና ዝግጅቶችዎ እስከመጨረሻው ይሰረዛሉ። ይህ ወደ ኋላ ሊመለስ አይችልም።','All your settings, including email templates and template formats for Events Manager will be deleted.'=>'የ Events Manager የኢሜይል አብነቶችን እና የአብነት ቅርጸቶችን ጨምሮ ሁሉም ቅንብሮችዎ ይሰረዛሉ።','Allow %s to appear in the built-in search results.'=>'%s በውስጠ-ገብ የፍለጋ ውጤቶች ውስጥ እንዲታዩ ፍቀድ።','Allow Maybe?'=>'"ምናልባት" ይፈቀድ?','Allow Multiple Uploads'=>'በርካታ ሰቀላዎችን ፍቀድ','Allow RSVP Actions'=>'የምላሽ ይስጡ እርምጃዎችን ፍቀድ','Allow WordPress post-style archives.'=>'የWordPress ፖስት ዓይነት መዝገቦችን ፍቀድ።','Allow anonymous event submissions?'=>'ስም-አልባ የዝግጅት ማስረከቦችን ፍቀድ?','Allow bookings with registered emails?'=>'በተመዘገቡ ኢሜይሎች ቦታ ማስያዝ ይፈቀድ?','Allow double bookings?'=>'ድርብ ቦታ ማስያዝ ይፈቀድ?','Allow format shortcode parameters?'=>'የቅርጸት ሾርትኮድ ግቤቶች ይፈቀዱ?','Allow guest bookings?'=>'የእንግዳ ቦታ ማስያዝ ይፈቀድ?','Allow overbooking when approving?'=>'በማጽደቅ ጊዜ ከልክ በላይ ማስያዝ ይፈቀድ?','Allow subsites to create their own'=>'ንዑስ ጣቢያዎች የራሳቸውን እንዲፈጥሩ ፍቀድ','Allow users to respond with a \'Maybe\' status rather than Attending or Not Attending'=>'ተጠቃሚዎች ከመሳተፍ ወይም ካለመሳተፍ ይልቅ በ\'ምናልባት\' ሁኔታ እንዲመልሱ ፍቀድ','Allowed Extensions'=>'የተፈቀዱ ቅጥያዎች','Already Booked'=>'አስቀድሞ ተይዟል','Already attending'=>'አስቀድሞ ተሳታፊ ነው','Already booked'=>'አስቀድሞ ተይዟል','Already have a license? Download the plugin from %s, upload it under Plugins > Add New Plugin, then activate your license from its settings.'=>'አስቀድሞ ፈቃድ አለዎት? ተሰኪውን ከ%s ያውርዱ፣ በተሰኪዎች > አዲስ ተሰኪ አክል ስር ይስቀሉት፣ ከዚያ ፈቃድዎን ከቅንብሮቹ ያግብሩ።','Already migrated: %s'=>'አስቀድሞ ተሸጋግሯል፦ %s','Also, the following will occur:'=>'እንዲሁም የሚከተለው ይከሰታል:','Always check the latest stable version?'=>'ሁልጊዜ የቅርብ ጊዜውን የተረጋጋ ሥሪት ይፈተሽ?','Always show and ask for consent'=>'ሁልጊዜ አሳይ እና ፈቃድ ጠይቅ','An email will be sent to an administrator of your choice when an event is published by users who are not administrators.'=>'አስተዳዳሪ ያልሆኑ ተጠቃሚዎች ዝግጅት ሲያትሙ እርስዎ ወደመረጡት አስተዳዳሪ ኢሜይል ይላካል።','An email will be sent to the event contact if someone cancels their booking.'=>'አንድ ሰው ቦታ ማስያዙን ከሰረዘ ወደ የዝግጅቱ አድራሻ ኢሜይል ይላካል።','An email will be sent to the event owner when their event is approved. Users requiring event approval do not have the <code>publish_events</code> capability.'=>'ዝግጅቱ ሲጸድቅ ወደ የዝግጅቱ ባለቤት ኢሜይል ይላካል። ዝግጅት ማጽደቅ የሚያስፈልጋቸው ተጠቃሚዎች የ<code>publish_events</code> ችሎታ የላቸውም።','An email will be sent to your administrator emails when an event is submitted and pending approval.'=>'ዝግጅት ሲቀርብና ማጽደቅ ሲጠብቅ ወደ አስተዳዳሪ ኢሜይሎችዎ ኢሜይል ይላካል።','An error has occurred, not all sites were upgraded successfully.'=>'ስህተት ተከስቷል፣ ሁሉም ጣቢያዎች በተሳካ ሁኔታ አልተሻሻሉም።','An error occurred.'=>'ስህተት ተከስቷል።','An event with no bookings.'=>'ቦታ ማስያዝ የሌለው ዝግጅት።','An event with this name and start is already on this site (event %d).'=>'በዚህ ስምና መጀመሪያ ያለ ዝግጅት በዚህ ጣቢያ ላይ አለ (ዝግጅት %d)።','An import is running. Wait for it to finish, or pause it first.'=>'ማስገባት በሂደት ላይ ነው። እስኪጠናቀቅ ይጠብቁ፣ ወይም መጀመሪያ ያቁሙት።','An organizer with this name is already on this site.'=>'በዚህ ስም ያለ አዘጋጅ በዚህ ጣቢያ ላይ አለ።','And much more'=>'እና ሌሎችም ብዙ','Anonymous Submitter Info'=>'ያለስም አስገቢ መረጃ','Anonymous event submissions'=>'ስም-አልባ የዝግጅት ማስረከቦች','Anonymous submitters cannot see or modify their event once submitted. You can customize the success message they see here.'=>'ስም-አልባ አስረካቢዎች ዝግጅታቸው ከተላከ በኋላ ማየት ወይም ማሻሻል አይችሉም። የሚያዩትን የስኬት መልእክት እዚህ ማበጀት ይችላሉ።','Another request is already updating this online location.'=>'ሌላ ጥያቄ ይህን የመስመር ላይ አካባቢ አስቀድሞ እያዘመነ ነው።','Any Type'=>'ማንኛውም ዓይነት','Appears as the first default search option.'=>'እንደ መጀመሪያው ነባሪ የፍለጋ አማራጭ ይታያል።','Appears as the label for this search option.'=>'ለዚህ የፍለጋ አማራጭ እንደ መሰየሚያ ይታያል።','Appears on the text search filter above the categories list.'=>'ከምድቦች ዝርዝር በላይ ባለው የጽሑፍ ፍለጋ ማጣሪያ ላይ ይታያል።','Appears on the text search filter above the tags list.'=>'ከመለያዎች ዝርዝር በላይ ባለው የጽሑፍ ፍለጋ ማጣሪያ ላይ ይታያል።','Appears within the input box.'=>'በግብዓት ሳጥኑ ውስጥ ይታያል።','Apply global capabilities?'=>'ዓለም አቀፍ ችሎታዎችን ተግብር?','Approval Required?'=>'ማጽደቅ ያስፈልጋል?','Approve'=>'ጸድቅ','Approved'=>'ጸደቀ','Archetype'=>'ዓይነተ-ምሳሌ','Archetypes UI Builder'=>'የአርኪታይፕስ የተጠቃሚ በይነገጽ ገንቢ','Are current events past events?'=>'ወቅታዊ ዝግጅቶች ያለፉ ዝግጅቶች ናቸው?','Are you sure you want to cancel your booking?'=>'ቦታ ማስያዝዎን መሰረዝ እንደሚፈልጉ እርግጠኛ ነዎት?','Are you sure you want to continue?'=>'መቀጠል እንደሚፈልጉ እርግጠኛ ነዎት?','Are you sure you want to convert all repeating events into recurring events?'=>'ሁሉንም ተደጋጋሚ ዝግጅቶች ወደ ተደጋጋሚ ዝግጅቶች መቀየር እንደሚፈልጉ እርግጠኛ ነዎት?','Are you sure you want to convert this repeating event?'=>'ይህንን ተደጋጋሚ ዝግጅት መቀየር እንደሚፈልጉ እርግጠኛ ነዎት?','Are you sure you want to delete all recurrences of this event?'=>'የዚህን ዝግጅት ሁሉንም ድግግሞሾች መሰረዝ እንደሚፈልጉ እርግጠኛ ነዎት?','Are you sure you want to delete this archetype? This action cannot be undone.'=>'ይህን አርኪታይፕ መሰረዝ እንደሚፈልጉ እርግጠኛ ነዎት? ይህ ተግባር ሊቀለበስ አይችልም።','Are you sure you want to delete this file? It will be deleted upon submission.'=>'ይህንን ፋይል መሰረዝ እንደሚፈልጉ እርግጠኛ ነዎት? ሲያስገቡ ይሰረዛል።','Are you sure you want to delete this item? This action cannot be undone.'=>'ይህንን ንጥል መሰረዝ እንደሚፈልጉ እርግጠኛ ነዎት? ይህ እርምጃ መልሶ ሊመለስ አይችልም።','Are you sure you want to delete this ticket?'=>'ይህንን ትኬት መሰረዝ እንደሚፈልጉ እርግጠኛ ነዎት?','Are you sure you want to delete this ticket? All bookings related to this ticket will be deleted once you save this %s.'=>'ይህንን ትኬት መሰረዝ እንደሚፈልጉ እርግጠኛ ነዎት? ይህንን %s ካስቀመጡ በኋላ ከዚህ ትኬት ጋር የተያያዙ ሁሉም ቦታ ማስያዣዎች ይሰረዛሉ።','Are you sure you want to delete?'=>'መሰረዝ እንደሚፈልጉ እርግጠኛ ነዎት?','Are you sure you want to delete? This action cannot be undone.'=>'መሰረዝ እንደሚፈልጉ እርግጠኛ ነዎት? ይህ እርምጃ መልሶ ሊመለስ አይችልም።','Are you sure you want to detach this event? By doing so, this event will be independent of the recurring set of events.'=>'ይህንን ዝግጅት መለየት እንደሚፈልጉ እርግጠኛ ነዎት? ይህን ማድረግ ዝግጅቱን ከተደጋጋሚ የዝግጅቶች ስብስብ ራሱን የቻለ ያደርገዋል።','Are you sure you want to disable bookings? If you do this and save, you will lose all previous bookings. If you wish to prevent further bookings, reduce the number of spaces available to the amount of bookings you currently have'=>'ቦታ ማስያዝን ማሰናከል እንደሚፈልጉ እርግጠኛ ነዎት? ይህን ካደረጉ እና ካስቀመጡ ሁሉንም የቀድሞ ቦታ ማስያዣዎች ያጣሉ። ተጨማሪ ቦታ ማስያዝን ለመከላከል ከፈለጉ፣ የሚገኙትን ቦታዎች ብዛት አሁን ወዳሉት ቦታ ማስያዣዎች ብዛት ይቀንሱ','Are you sure you want to proceed? We recommend you back up your database first, just in case!'=>'መቀጠል እንደሚፈልጉ እርግጠኛ ነዎት? ለማንኛውም ጉዳይ መጀመሪያ የውሂብ ጎታዎን እንዲያስቀምጡ እንመክራለን!','Are you sure you want to reset Events Manager?'=>'Events Managerን ዳግም ማቀናበር እንደሚፈልጉ እርግጠኛ ነዎት?','Are you sure you want to uninstall Events Manager?'=>'Events Managerን ማራገፍ እንደሚፈልጉ እርግጠኛ ነዎት?','As a site admin, you see all group events, users will only be able to choose groups they are admins of.'=>'እንደ ጣቢያ አስተዳዳሪ ሁሉንም የቡድን ዝግጅቶች ታያለህ፤ ተጠቃሚዎች ግን የሚያስተዳድሯቸውን ቡድኖች ብቻ መምረጥ ይችላሉ።','Ascending'=>'ሽቅብ','Aside from pages we automatically generate and include certain jQuery files, if you are using Widgets, Shortcode or PHP to display specific items you may need to tell us where you are using them for them to work properly. Below are options for you to include specific jQuery dependencies only on certain pages.'=>'በራስ-ሰር ከምንፈጥራቸው ገጾች በተጨማሪ እና የተወሰኑ jQuery ፋይሎችን ከምናካትታቸው በተጨማሪ፣ የተወሰኑ ንጥሎችን ለማሳየት ምግባሮችን፣ አጭር ኮድን ወይም PHP የሚጠቀሙ ከሆነ በትክክል እንዲሠሩ የት እንደሚጠቀሙባቸው ሊነግሩን ይችላል። ከታች የተወሰኑ jQuery ጥገኝነቶችን በተወሰኑ ገጾች ላይ ብቻ ለማካተት አማራጮች አሉ።','Attachment ID not found.'=>'የአባሪ መታወቂያ አልተገኘም።','Attendee %d'=>'ተሳታፊ %d','Attendee %s'=>'ተሳታፊ %s','Attendee (Per Space Booked)'=>'ተሳታፊ (በእያንዳንዱ የተያዘ ቦታ)','Attendee names, answers to attendee fields and check-in status are copied and kept with each ticket. Without Events Manager Pro they are not shown, so you will see each booking, its tickets and the person who booked.'=>'የተሳታፊ ስሞች፣ ለተሳታፊ መስኮች የተሰጡ መልሶችና የመግቢያ ሁኔታ ተገልብጠው ከእያንዳንዱ ትኬት ጋር ይቀመጣሉ። Events Manager Pro ከሌለ አይታዩም፣ ስለዚህ እያንዳንዱን ቦታ ማስያዝ፣ ትኬቶቹን እና ያስያዘውን ሰው ያያሉ።','Attendees'=>'ተሳታፊዎች','Attending'=>'ይሳተፋሉ','Attributes'=>'ባህሪያት','AutoTLS'=>'ራስ-ሰር TLS','Avail. Spaces'=>'የሚገኙ ቦታዎች','Availability'=>'ተገኝነት','Available'=>'የሚገኝ ነው','Available Archetypes'=>'የሚገኙ አርኪታይፕስ','Available Spaces'=>'የሚገኙ ቦታዎች','Available for'=>'የሚገኘው ለ','Available from'=>'ከዚህ ጀምሮ ይገኛል','Available spaces'=>'የሚገኙ ቦታዎች','Available until'=>'እስከዚህ ድረስ ይገኛል','Average Sale'=>'አማካይ ሽያጭ','Average Ticket'=>'አማካይ ትኬት','Awaiting Online Payment'=>'የመስመር ላይ ክፍያ በመጠበቅ ላይ','Awaiting Payment'=>'ክፍያ በመጠበቅ ላይ','Bar Graph'=>'የአምድ ግራፍ','Base Event Settings'=>'መሰረታዊ የዝግጅት ቅንብሮች','Base Location Settings'=>'መሰረታዊ የአካባቢ ቅንብሮች','Base font size'=>'መሠረታዊ የቅርጸ ቁምፊ መጠን','Base font weight'=>'መሠረታዊ የቅርጸ ቁምፊ ክብደት','Base line height'=>'መሠረታዊ የመስመር ቁመት','Basic HTML is allowed in ticket labels and descriptions.'=>'በትኬት መለያዎች እና መግለጫዎች ውስጥ መሠረታዊ HTML ይፈቀዳል።','Basic Only'=>'መሠረታዊ ብቻ','Be aware that some themes will not work with this option, if so (or you want to make your own changes), you can create a file named <code>single-%s.php</code> <a href=\'#\'>as shown on the WordPress codex</a>, and leave this set to Posts.'=>'አንዳንድ ገጽታዎች ከዚህ አማራጭ ጋር እንደማይሠሩ ይወቁ፣ እንደዚያ ከሆነ (ወይም የራስዎን ለውጦች ማድረግ ከፈለጉ)፣ <code>single-%s.php</code> የሚባል ፋይል <a href=\'#\'>በWordPress codex ላይ እንደሚታየው</a> መፍጠር እና ይህንን ወደ ፖስቶች ተዋቅሮ መተው ይችላሉ።','Before'=>'በፊት','Before you save your changes, you can quickly send yourself a test email by clicking this button.'=>'ለውጦችዎን ከማስቀመጥዎ በፊት ይህን ቁልፍ ጠቅ በማድረግ ለራስዎ የሙከራ ኢሜይል በፍጥነት መላክ ይችላሉ።','Below are translations for your location address. If left blank, the language of the original event will be used.'=>'ከታች ለአካባቢዎ አድራሻ ትርጉሞች አሉ። ባዶ ከተተዉ የዋናው ዝግጅት ቋንቋ ጥቅም ላይ ይውላል።','Below are translations for your tickets. If left blank, the language of the original event will be used.'=>'ከታች ለትኬቶችዎ ትርጉሞች አሉ። ባዶ ከተተዉ የዋናው ዝግጅት ቋንቋ ጥቅም ላይ ይውላል።','Below you will find texts that will be displayed to users in various areas during the bookings process, particularly on booking forms.'=>'ከታች በቦታ ማስያዝ ሂደት ወቅት በተለያዩ ቦታዎች በተለይም በቦታ ማስያዣ ቅጾች ላይ ለተጠቃሚዎች የሚታዩ ጽሑፎችን ያገኛሉ።','Block Editor (Gutenberg)'=>'የመደብ አርታዒ (Gutenberg)','Block Editor development is still ongoing, switch back to the Classic Editor if you experience issues.'=>'የመደብ አርታዒ ልማት አሁንም በሂደት ላይ ነው፤ ችግር ካጋጠመዎት ወደ የድሮ አርታዒ ይመለሱ።','Block editor layout'=>'የመደብ አርታዒ አቀማመጥ','Blog Default Timezone'=>'የጦማር መደበኛ የጊዜ ክልል','Body Classes'=>'የአካል ክፍሎች','Book Now'=>'አሁን ቦታ ያስይዙ','Book N